import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Branded — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Branded — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/branded"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Branded — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/branded"}]]},"headers":[],"relativePath":"user-guide/branded.md","filePath":"user-guide/branded.md","lastUpdated":1788122084000}'),r={name:"user-guide/branded.md"};function i(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="branded-—-user-guide" tabindex="-1">Branded — User Guide <a class="header-anchor" href="#branded-—-user-guide" aria-label="Permalink to &quot;Branded — User Guide&quot;">​</a></h1><p>The <strong>Branded</strong> marketplace module lets a workspace map a <strong>custom domain</strong> and use its brand name / logo in emails and web push notifications.</p><h2 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h2><p>Billable platform add-on (catalog slug <code>branded</code>):</p><table tabindex="0"><thead><tr><th>Cycle</th><th>Price (USD)</th></tr></thead><tbody><tr><td>Monthly</td><td><strong>$29</strong></td></tr><tr><td>Yearly</td><td><strong>$290</strong></td></tr></tbody></table><p>Not default-included — purchase from Marketplace (<code>is_billable = true</code>). See <a href="/developer-guide/entitlements">Entitlements</a> for the full catalog table.</p><h2 id="who-can-use-it" tabindex="-1">Who can use it <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who can use it&quot;">​</a></h2><ol><li>Purchase or install <strong>Branded</strong> from Marketplace (<code>module:branded</code>).</li><li>You need permission <strong>View branded</strong> / <strong>Manage branded</strong> (<code>branded.view</code> / <code>branded.manage</code>). Workspace admins get both by default.</li></ol><p>Without the module, the Settings <strong>Domain</strong> tab is hidden and custom hostnames never bind to the workspace — even if someone points DNS or an IP at the server.</p><h2 id="map-a-custom-domain" tabindex="-1">Map a custom domain <a class="header-anchor" href="#map-a-custom-domain" aria-label="Permalink to &quot;Map a custom domain&quot;">​</a></h2><ol><li>Open <strong>Settings → Domain</strong>.</li><li><strong>Step 1 — Enter your website address</strong> (for example <code>myai.com.pk</code> or <code>app.domain.co.uk</code>; multi-part ccTLDs are supported) and choose <strong>Continue</strong>.</li><li><strong>Step 2 — Connect it at your domain provider</strong> (GoDaddy, Namecheap, Cloudflare, etc.): <ul><li><strong>TXT</strong> — prove you own the address (<code>_elosync-verification.{hostname}</code>).</li><li><strong>A</strong> — point <code>{hostname}</code> to the platform IP shown in Settings.</li><li><strong>CNAME</strong> — point <code>www.{hostname}</code> to <code>{hostname}</code> so the <code>www</code> version works too.</li><li>Advanced: optional AAAA or platform CNAME target when your operator provides them.</li></ul></li><li><strong>Step 3 — Check the connection</strong>: choose <strong>I’ve added the records — Check now</strong>.</li></ol><p>DNS can take a few minutes (sometimes up to 24 hours). After the check succeeds, Settings shows <strong>DNS verified</strong> and <strong>Pending SSL certificate</strong> while the platform operator enables secure hosting (TLS certificate) on the server. Your custom <code>https://</code> address becomes fully <strong>Active</strong> only after that step — often within 24 hours. Continue using your platform address (for example <code>app.elosync.com</code>) until the custom URL works in your browser.</p><p>Pointing an IP alone does not activate the workspace. <strong>Active</strong> in the UI means DNS + SSL are both complete.</p><p>Platform subdomains (for example <code>acme.localhost</code>) stay managed by Central — they are not configured on this tab.</p><h2 id="hosting-status" tabindex="-1">Hosting status <a class="header-anchor" href="#hosting-status" aria-label="Permalink to &quot;Hosting status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UI badge</th><th>Meaning</th></tr></thead><tbody><tr><td>Waiting for DNS</td><td>TXT / A records not verified yet</td></tr><tr><td>DNS verified + Pending SSL certificate</td><td>Records are correct; secure hosting is being set up</td></tr><tr><td>Connected + Active</td><td>Custom <code>https://</code> address is ready</td></tr></tbody></table><h2 id="brand-in-notifications" tabindex="-1">Brand in notifications <a class="header-anchor" href="#brand-in-notifications" aria-label="Permalink to &quot;Brand in notifications&quot;">​</a></h2><p>While Branded is active:</p><ul><li>Tenant emails use your application / company name, logo, and button color in the mail chrome.</li><li>The email footer shows your brand copyright plus a small <strong>Powered by EloSync</strong> line.</li><li>Web push notifications use your logo / favicon and prefix titles with your application name.</li></ul><p>Without Branded, tenant emails use the <strong>platform (EloSync) logo and app name</strong> from Central branding — not a blank text-only header (and no “Powered by” line). Visual SPA branding (Settings → Branding) remains available to all workspaces; custom domains and web-push white-label require Branded.</p><p>Notification emails (assignments, mentions, verify/reset, digests) use a professional card layout with a primary action button such as <strong>View task</strong> or <strong>Verify Email Address</strong>.</p><h2 id="remove-or-cancel" tabindex="-1">Remove or cancel <a class="header-anchor" href="#remove-or-cancel" aria-label="Permalink to &quot;Remove or cancel&quot;">​</a></h2><ul><li><strong>Remove</strong> on the Domain tab deletes the custom hostname mapping.</li><li>Cancelling the Branded subscription clears verification so the custom host stops resolving.</li></ul>',23)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
